// Throwaway verification harness for the Alt+A monster easter egg.
// Lives outside the client project and gets deleted afterwards.
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { spawn } from 'node:child_process';

const SITE = '<home>/source/repos/priv/monster-dev-testruns/2026-08-01-phase2b';
const OUT = '<home>/AppData/Local/Temp/monster-dev-check';
const CHROME = 'C:/Program Files/Google/Chrome/Application/chrome.exe';
const TYPES = { '.html': 'text/html', '.css': 'text/css', '.js': 'text/javascript', '.png': 'image/png', '.svg': 'image/svg+xml' };

const requested = [];
const server = http.createServer((req, res) => {
  const rel = req.url.split('?')[0] === '/' ? '/index.html' : req.url.split('?')[0];
  requested.push(rel);
  const file = path.join(SITE, decodeURIComponent(rel));
  if (!fs.existsSync(file)) { res.writeHead(404).end('nope'); return; }
  res.writeHead(200, { 'content-type': TYPES[path.extname(file)] || 'application/octet-stream' });
