    await cdp('Input.dispatchKeyEvent', { type, modifiers: mods, code: 'KeyA', key: 'a', windowsVirtualKeyCode: 65, nativeVirtualKeyCode: 65 });
  }
};

await cdp('Runtime.enable');
await cdp('Page.navigate', { url: 'http://127.0.0.1:8732/' });
await sleep: {}
await sleep(1000);

const overflowBaseline = await evaluate('({ scrollW: document.documentElement.scrollWidth, clientW: document.documentElement.clientWidth })');
console.log('baseline (no monster):', overflowBaseline);

await key(1); // Alt
await sleep(300);
console.log('monster present:', await evaluate("document.querySelectorAll('.monster').length"));

// sample overflow across the whole crossing, including the far right edge
let worst = 0;
for (let i = 0; i < 24; i++) {
  await sleep(450);
  const o = await evaluate('({ x: Math.round(document.querySelector(".monster")?.getBoundingClientRect().left ?? NaN), over: document.documentElement.scrollWidth - document.documentElement.clientWidth })');
  worst = Math.max(worst, o.over);
  if (i % 6 === 0 || o.over > 0) console.log('  sample', i, o);
}
console.log('worst horizontal overflow during walk:', worst, 'px');
console.log('monster after crossing:', await evaluate("document.querySelectorAll('.monster').length"));

console.log('\nCtrl+Alt+A (modifiers 3 = alt|ctrl):');
await key(3);
await sleep(250);
console.log('  monsters:', await evaluate("document.querySelectorAll('.monster').length"));

console.log('\nAlt+Shift+A (modifiers 9 = alt|shift):');
await key(9);
await sleep(250);
console.log('  monsters:', await evaluate("document.querySelectorAll('.monster').length"));

ws.close(); chrome.kill(); server.close(); process.exit(0);

